      <div class="subvalue">${(p.itemDiscount||0)>0?`İkram/Ürün: ${b(p.itemDiscount)} | `:""}${(p.orderDiscount||0)>0?`Genel: ${b(p.orderDiscount)} | `:""}${p.cancelledItemsCount} iptal (${b(p.cancelledItemsLoss)})</div>
